def clean(df):
    df = df.copy()
    # Drop exact duplicate rows
    df = df.drop_duplicates()
    # Fix Category label variants
    cat_map = {
        'Office Suplies': 'Office Supplies',
        'Accesories': 'Accessories',
    }
    df['Category'] = df['Category'].replace(cat_map)
    # Fix Region extra spaces
    df['Region'] = df['Region'].str.strip()
    return df

def answer(df):
    df = clean(df)
    res = {}
    grouped = df.groupby('Category')['Price'].mean()
    for cat, val in grouped.items():
        res[cat] = float(val)
    return res
